/**
 * Checks whether a decoded escape character is "unreserved" per R2:
 * a letter A-Z or a-z, a digit, or one of `-` `.` `_` `~`.
 *
 * @param {string} ch
 * @returns {boolean}
 */
function isUnreserved(ch) {
	return (
		(ch >= "A" && ch <= "Z") ||
		(ch >= "a" && ch <= "z") ||
		(ch >= "0" && ch <= "9") ||
		ch === "-" ||
		ch === "." ||
		ch === "_" ||
		ch === "~"
	);
}

/** @param {string} path @returns {string} */
export function normalizeRoute(path) {
	// R1: must be a string, start with "/", contain no "?" or "#".
	if (
		typeof path !== "string" ||
		path.length === 0 ||
		path[0] !== "/" ||
		path.includes("?") ||
		path.includes("#")
	) {
		throw new TypeError(
			'path must be a string starting with "/" and containing no "?" or "#"',
		);
	}

	// R2: percent-escapes are processed before anything else.
	let decoded = "";
	for (let i = 0; i < path.length; i++) {
		const ch = path[i];
		if (ch !== "%") {
			decoded += ch;
			continue;
		}
		const hex = path.slice(i + 1, i + 3);
		if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
			throw new SyntaxError(`invalid percent escape at index ${i}`);
		}
		const c = String.fromCharCode(parseInt(hex, 16));
		if (isUnreserved(c)) {
			decoded += c;
		} else {
			decoded += "%" + hex.toUpperCase();
		}
		i += 2; // skip the two hex digits
	}

	// R3 + R4: split into segments, collapsing repeated slashes.
	const parts = decoded.split("/");
	const segments = [];
	for (const seg of parts) {
		if (seg === "") continue; // repeated/trailing slashes count as one
		if (seg === ".") continue; // dot segment is removed
		if (seg === "..") {
			if (segments.length === 0) {
				throw new RangeError("a \"..\" segment with no segment before it");
			}
			segments.pop();
		} else {
			segments.push(seg);
		}
	}

	// R5: trailing slash if the original (post-R2) path ends with "/" or
	// its last segment is "." or "..".
	let last = null;
	for (let k = parts.length - 1; k >= 0; k--) {
		if (parts[k] !== "") {
			last = parts[k];
			break;
		}
	}
	const trailing =
		decoded.endsWith("/") || last === "." || last === "..";

	if (segments.length === 0) {
		return "/";
	}
	const joined = "/" + segments.join("/");
	return trailing ? joined + "/" : joined;
}

